   906  // Returns `true` and updates the `aError` on success.
   907  bool NcpBase::HandlePropertySetForSpecialProperties(uint8_t aHeader, spinel_prop_key_t aKey, otError &aError)
   908  {
   909      bool didHandle = true;
   910
   911      // Here the properties that require special treatment are handled.
   912      // These properties are expected to form/write the response from
   913      // their set handler directly.
   914
   915      switch (aKey)
   916      {
   917      case SPINEL_PROP_HOST_POWER_STATE:
   918          ExitNow(aError = HandlePropertySet_SPINEL_PROP_HOST_POWER_STATE(aHeader));
   919
   920  #if OPENTHREAD_ENABLE_DIAG
   921      case SPINEL_PROP_NEST_STREAM_MFG:
   922          ExitNow(aError = HandlePropertySet_SPINEL_PROP_NEST_STREAM_MFG(aHeader));
   923  #endif
   924
   925  #if OPENTHREAD_FTD && OPENTHREAD_ENABLE_COMMISSIONER
   926      case SPINEL_PROP_THREAD_COMMISSIONER_ENABLED:
   927          ExitNow(aError = HandlePropertySet_SPINEL_PROP_THREAD_COMMISSIONER_ENABLED(aHeader));
   928  #endif
   929
   930  #if OPENTHREAD_RADIO || OPENTHREAD_ENABLE_RAW_LINK_API
   931      case SPINEL_PROP_STREAM_RAW:
   932          ExitNow(aError = HandlePropertySet_SPINEL_PROP_STREAM_RAW(aHeader));
   933  #endif
   934
   935      default:
   936          didHandle = false;
   937          break;
   938      }
   939
   940  exit:
   941      return didHandle;
   942  }
